#!/usr/bin/env python3
"""Turn 35 Wave 41: transfer market refresh mechanics (refreshes per match; forfeits and scenarios/ads do NOT refresh; half-time live quit is the fastest refresh; the 20-40 gem 24-hour LOCK), the coin-farming-without-refreshing technique, released-player repurchase window, cannot buy a player you already own, market gating, scout prices, and the clan gem economy with the 50-vs-100 top-contributor conflict."""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w41')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid
def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid
os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-442: transfer market mechanics ----------
e_tm=new_ev("Bluestacks DLS26 character-development + free-rewards guides, gamingonphone DLS26 beginners/career guides, r/DreamLeagueSoccer 18gl9ob (Dec 2023), 1gaazjq (Oct 2024), 14vw8e4 (Jul 2023 lock player), 1hmlojp (Dec 2024), 196mf1c (Jan 2024), 1o82i9h (Oct 2025), 18a2llb (Dec 2023), 1gj7qmo (Nov 2024), 19c5vgk (Jan 2024), 1ap2595 (Feb 2024), 1kx4qe2 (May 2025), zwih6d, rajatips, supercheats, dream-league-soccer.fandom Free Transfers",
    "TRANSFER MARKET MECHANICS - THE MOST OPERATIONALLY IMPORTANT LAYER. REFRESH TRIGGER: the Live Transfer Market refreshes after every MATCH you play, so the more games you complete the more opportunities you get. CRITICAL EXCEPTIONS - what does NOT refresh it: FORFEITING a Career match does not refresh the market, and SCENARIOS, EXHIBITION matches and free ADS all earn coins WITHOUT updating the shop. This is the single most useful pairing of facts in the game, because it means you can farm coins for a specific target player without burning the market slot they are sitting in. DREAM DRAFT is also reported not to reset the shop. FASTEST REFRESH: quit a LIVE match at half-time - this changes the market fastest. An alternative is to play the first half of a live game and then forfeit. LOCK PLAYER: spend 20 or 40 GEMS to lock any player on the live transfer market for 24 HOURS. The player remains on the market even after you play the next game, a small lock sign appears on their card, and after the period they disappear as normal when you refresh. This is the paid, reliable answer to 'how do I wait for a specific player'. CONFLICTING REFRESH CADENCE: one source claims the market 'refreshes every 7 hours' rather than per match - probably a version difference or a confusion with the shop. REPURCHASE WINDOW: after releasing a player there is a grace period during which you can buy them back from the release area; once that window closes they enter the general transfer market. RELEASED PLAYERS DO REAPPEAR, but collection pieces never come back and rare or common cards may require a long wait. NO DUPLICATES: you cannot buy a player you already own - to get a new Bellingham or Vinicius Jr card you must first sell the one you have. TEAM-RATING LEVER: manipulating your team rating and then playing refreshes the window, and higher-rated teams see better players. The fastest general recipe is to buy the highest-rated player available at each refresh, which raises team strength and attracts better players. A community superstition holds that a wanted player will not appear until you have spent all your coins. TOP PICKS: legendary players can appear in the Window individually or as 'Top Picks'. SCOUT PRICES: Common Scout 75 coins, Legendary Scout 500 coins, with the Common Scout's 5% legendary chance considered good value for early progression. A guaranteed 80+ legendary player (the free Legendary Agent route) raises team rating and attracts interest, after which legendary players appear in the market for roughly 1,500-2,800 coins. BUILD TIME: one player needed about 300 matches after maxing the stadium to complete a dream squad lacking only Ronaldo and Messi. RELEASE vs SELL: releasing a player yields NO coins - it yields coaches - which is the foundation of the coach-farming loop. LEGACY: free transfers existed only up to DLS2016h, after which players are sold for half their purchase value. A red-card suspended player could be released and bought back from Free Transfers in DLS Classic, which erased season records but preserved upgraded stats.",
    "evidence/raw/turn35_w41/EV-442_transfer_market.html",
    "TRANSFER MARKET: refreshes after every MATCH played. CRITICAL - what does NOT refresh it: FORFEITING a career match, SCENARIOS, EXHIBITION matches and free ADS (all earn coins without updating the shop), and Dream Draft. This pairing lets you farm coins for a target player without burning their market slot. FASTEST REFRESH = quit a LIVE match at half-time (or play the first half and forfeit). LOCK PLAYER: 20 or 40 gems locks any player on the live transfer market for 24 HOURS - the paid answer to waiting for a specific player. CONFLICT: one source claims a 7-hour refresh rather than per-match. REPURCHASE WINDOW after releasing a player before they enter the general market. Released players DO reappear but collection pieces never do. NO DUPLICATES - you cannot buy a player you already own. Raising team rating attracts better players; buy the highest-rated player at each refresh. Top Picks carry legendary players. Scouts: Common 75c, Legendary 500c, Common's 5% legendary chance is good early value. A guaranteed 80+ legendary raises rating and attracts interest, after which legendaries appear for ~1,500-2,800 coins. ~300 matches after maxing the stadium to build a dream squad. RELEASE yields NO coins - only coaches",
    quality="community")

add_claim("The Live Transfer Market refreshes after every MATCH played, so the more games completed the more opportunities to find better players.", 2, "transfers/refresh-per-match", [e_tm])
add_claim("CRITICAL: forfeiting a Career match does NOT refresh the transfer market, and scenarios, exhibition matches and free ads all earn coins WITHOUT updating the shop - so you can farm coins for a target player without burning the market slot they occupy.", 2, "transfers/what-does-not-refresh", [e_tm], notes="Highest-value operational pairing in the game")
add_claim("Dream Draft is also reported not to reset the transfer shop.", 3, "transfers/draft-does-not-refresh", [e_tm])
add_claim("The fastest way to refresh the transfer market is to quit a LIVE match at half-time; playing the first half of a live game and then forfeiting also works.", 3, "transfers/fastest-refresh", [e_tm])
add_claim("LOCK PLAYER: spending 20 or 40 gems locks any player on the live transfer market for 24 hours, so they survive the next match refresh; a small lock sign appears on their card and they disappear as normal once the period ends.", 2, "transfers/lock-player-24h", [e_tm], notes="The paid answer to waiting for a specific player")
add_claim("CONFLICT on refresh cadence: the dominant account is per-match refresh, while one source claims the market refreshes every 7 hours.", 3, "transfers/refresh-cadence-conflict", [e_tm], notes="C-021 candidate")
add_claim("After releasing a player there is a grace period during which you can buy them back from the release area; once it closes they enter the general transfer market.", 3, "transfers/repurchase-window", [e_tm])
add_claim("Released players do reappear in the transfer market, but collection pieces never come back and rare or common cards may require a long wait.", 3, "transfers/released-players-reappear", [e_tm])
add_claim("NO DUPLICATES: you cannot buy a player you already own - to obtain a new version of a card you must first sell the one you have.", 2, "transfers/no-duplicates", [e_tm])
add_claim("Buy the highest-rated player available at each market refresh: this raises team strength and attracts better players, and higher-rated teams see better players more often.", 3, "transfers/buy-highest-to-raise-rating", [e_tm])
add_claim("Legendary players can appear in the transfer window individually or as 'Top Picks'.", 3, "transfers/top-picks", [e_tm])
add_claim("Scout prices: Common Scout 75 coins and Legendary Scout 500 coins, with the Common Scout's 5% legendary chance considered good value for early progression.", 3, "transfers/scout-prices", [e_tm])
add_claim("A guaranteed 80+ legendary player raises team rating and attracts interest, after which legendary players appear in the transfer market for roughly 1,500-2,800 coins.", 3, "transfers/legendary-price-band", [e_tm])
add_claim("RELEASE yields no coins - it yields coaches - which is the foundation of the coach-farming loop; one player needed about 300 matches after maxing the stadium to complete a dream squad.", 2, "economy/release-yields-coaches-not-coins", [e_tm])
add_claim("LEGACY: free transfers existed only up to DLS2016h, after which players are sold for half their purchase value; in DLS Classic a red-card suspended player could be released and bought back from Free Transfers, which erased season records but preserved upgraded stats.", 2, "errata/free-transfers-legacy", [e_tm])
add_claim("SPECULATIVE: a community method claims that renaming your manager to the target player's name and matching your manager nationality to theirs (or renaming your club to their club) makes that player appear within 20-40 matches. The poster explicitly states some claim it works and others that it does not.", 4, "errata/manager-name-method-speculative", [e_tm], notes="Do not rely on this")

# ---------- EV-443: clan gem economy ----------
