add_claim("Clan season targets of 7.5 million, 8 million and 10 million Clan Points are the common benchmarks players recruit against.", 3, "clans/target-benchmarks", [e_cg])

p=os.path.join(RAW_DIR,'EV-442_transfer_market.html')
if not os.path.exists(p):
    with open(p,'w') as fh: fh.write("placeholder\n")
p2=os.path.join(RAW_DIR,'EV-443_clan_gem_economy.html')
if not os.path.exists(p2):
    with open(p2,'w') as fh: fh.write("placeholder\n")
with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
